// Cross-language conformance: every vector in testdata/conformance was
// generated by cmd/tpconform from the Go implementation. The TypeScript
// port must reproduce identical values and snapshots — byte-compatible
// canonical JSON — or the SDKs would diverge.
import { describe, expect, it } from "vitest";
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { Document, type Op, type Schema } from "../src/crdt/document";
import { canonicalStringify } from "../src/canonical";
import { marshalSnapshot, unmarshalSnapshot, type SnapshotObject } from "../src/crdt/snapshot";

const conformanceDir = join(import.meta.dirname, "..", "..", "..", "testdata", "conformance");

interface Vector {
  schema: Schema;
  ops: Op[];
  expectedValues: Record<string, unknown>;
  expectedSnapshot: SnapshotObject;
}

const vectors = readdirSync(conformanceDir)
  .filter((name) => name.endsWith(".json"))
  .sort();

describe("cross-language conformance vectors", () => {
  it("finds all 50 vectors", () => {
    expect(vectors.length).toBe(50);
  });

  for (const name of vectors) {
    it(name, () => {
      const v = JSON.parse(readFileSync(join(conformanceDir, name), "utf-8")) as Vector;
      expect(v.ops.length).toBeGreaterThan(0);

      const doc = new Document(v.ops[0]!.key);
      v.ops.forEach((op, i) => {
        doc.apply(op, v.schema);
      });

      // Values compared as canonical JSON: expectedValues decode set fields
      // as plain arrays while the port returns string arrays, but their
      // canonical forms are identical, including map key order.
      expect(canonicalStringify(doc.values())).toBe(canonicalStringify(v.expectedValues));

      // Snapshot compared as canonical JSON on both sides: whitespace and
      // key order normalized, content exact.
      const snap = marshalSnapshot(doc);
      expect(canonicalStringify(snap)).toBe(canonicalStringify(v.expectedSnapshot));

      // Loading the expected snapshot must yield the expected values.
      const loaded = unmarshalSnapshot(v.expectedSnapshot);
      expect(canonicalStringify(loaded.values())).toBe(canonicalStringify(v.expectedValues));
    });
  }
});
